<?php
require dirname(__DIR__).'/bootstrap.php';
use App\Core\Database;
function table62(string $t):bool{try{return (bool)Database::one('SELECT 1 FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=? LIMIT 1',[$t]);}catch(Throwable){return false;}}
try{Database::exec("ALTER TABLE donations MODIFY payment_method ENUM('bank_transfer','cash','other','online_payment') NOT NULL DEFAULT 'bank_transfer'");}catch(Throwable $e){}
if(!table62('payment_gateway_configs')) Database::exec("CREATE TABLE payment_gateway_configs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,provider VARCHAR(60) NOT NULL UNIQUE,enabled TINYINT(1) NOT NULL DEFAULT 0,mode ENUM('sandbox','live') NOT NULL DEFAULT 'sandbox',merchant_id VARCHAR(160) NULL,merchant_secret_enc MEDIUMTEXT NULL,api_app_id VARCHAR(190) NULL,api_app_secret_enc MEDIUMTEXT NULL,currency CHAR(3) NOT NULL DEFAULT 'LKR',min_amount DECIMAL(14,2) NOT NULL DEFAULT 100.00,max_amount DECIMAL(14,2) NOT NULL DEFAULT 1000000.00,receipt_prefix VARCHAR(20) NOT NULL DEFAULT '97D',receipt_email_enabled TINYINT(1) NOT NULL DEFAULT 0,last_test_status VARCHAR(30) NOT NULL DEFAULT 'never',last_test_message VARCHAR(500) NULL,last_test_at DATETIME NULL,updated_by BIGINT UNSIGNED NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,CONSTRAINT fk_payment_gateway_updated_by FOREIGN KEY(updated_by) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB");
if(!table62('payment_transactions')) Database::exec("CREATE TABLE payment_transactions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,public_id VARCHAR(64) NOT NULL UNIQUE,donation_id BIGINT UNSIGNED NULL UNIQUE,campaign_id BIGINT UNSIGNED NULL,gateway VARCHAR(60) NOT NULL,gateway_order_id VARCHAR(120) NOT NULL UNIQUE,gateway_payment_id VARCHAR(120) NULL UNIQUE,status ENUM('pending','processing','successful','failed','cancelled','refunded') NOT NULL DEFAULT 'pending',amount DECIMAL(14,2) NOT NULL,currency CHAR(3) NOT NULL DEFAULT 'LKR',donor_name VARCHAR(160) NOT NULL,donor_email VARCHAR(190) NULL,donor_phone VARCHAR(60) NOT NULL,donor_address VARCHAR(500) NULL,donor_city VARCHAR(120) NULL,donor_country VARCHAR(120) NOT NULL DEFAULT 'Sri Lanka',payment_method_preference VARCHAR(40) NULL,payment_method VARCHAR(80) NULL,gateway_status_code VARCHAR(30) NULL,receipt_number VARCHAR(80) NULL UNIQUE,callback_signature_hash CHAR(64) NULL,callback_received_at DATETIME NULL,paid_at DATETIME NULL,failed_at DATETIME NULL,cancelled_at DATETIME NULL,refunded_at DATETIME NULL,last_verified_at DATETIME NULL,retry_count INT UNSIGNED NOT NULL DEFAULT 0,metadata_json JSON NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,CONSTRAINT fk_payment_transaction_donation FOREIGN KEY(donation_id) REFERENCES donations(id) ON DELETE SET NULL,CONSTRAINT fk_payment_transaction_campaign FOREIGN KEY(campaign_id) REFERENCES campaigns(id) ON DELETE SET NULL,INDEX idx_payment_status_date(status,created_at),INDEX idx_payment_donor_email(donor_email),INDEX idx_payment_gateway_date(gateway,created_at),INDEX idx_payment_paid_at(paid_at)) ENGINE=InnoDB");
if(!table62('payment_webhook_events')) Database::exec("CREATE TABLE payment_webhook_events (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,gateway VARCHAR(60) NOT NULL,event_hash CHAR(64) NOT NULL UNIQUE,order_id VARCHAR(120) NOT NULL,status_code VARCHAR(20) NULL,verified TINYINT(1) NOT NULL DEFAULT 0,payload_json JSON NULL,received_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX idx_payment_webhook_order(order_id,received_at)) ENGINE=InnoDB");
Database::exec("INSERT INTO payment_gateway_configs(provider,enabled,mode,currency,min_amount,max_amount,receipt_prefix,receipt_email_enabled) VALUES('payhere',0,'sandbox','LKR',100.00,1000000.00,'97D',0) ON DUPLICATE KEY UPDATE provider=VALUES(provider)");
echo "V6.2 online donation and payment gateway upgrade completed.\n";
